import javax.swing.*;import java.awt.*;import java.sql.Timestamp;
public final class LoginFrame extends JFrame {private static final Dimension FIELD_SIZE=new Dimension(300,36);private final JTextField username=new JTextField(18);private final JPasswordField password=new JPasswordField(18);private final JLabel error=new JLabel(" ");public LoginFrame(){super("Payroll System Login");username.setPreferredSize(FIELD_SIZE);username.setMinimumSize(FIELD_SIZE);username.setMaximumSize(FIELD_SIZE);password.setPreferredSize(FIELD_SIZE);password.setMinimumSize(FIELD_SIZE);password.setMaximumSize(FIELD_SIZE);setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);setMinimumSize(new Dimension(720,360));JPanel form=new JPanel(new GridBagLayout());form.setBorder(BorderFactory.createEmptyBorder(38,52,38,52));GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(9,9,9,9);c.fill=GridBagConstraints.HORIZONTAL;c.gridx=0;c.gridy=0;c.gridwidth=2;c.weightx=1;JLabel title=new JLabel("Payroll System",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,26f));form.add(title,c);c.gridwidth=1;c.weightx=0;c.gridy++;form.add(new JLabel("Username"),c);c.gridx=1;c.weightx=1;form.add(username,c);c.gridx=0;c.gridy++;c.weightx=0;form.add(new JLabel("Password"),c);c.gridx=1;c.weightx=1;form.add(password,c);c.gridx=0;c.gridy++;c.gridwidth=2;c.weightx=1;error.setForeground(Color.RED);error.setHorizontalAlignment(SwingConstants.CENTER);error.setPreferredSize(new Dimension(600,28));form.add(error,c);c.gridy++;JButton login=new JButton("Login");login.addActionListener(e->login());form.add(login,c);getRootPane().setDefaultButton(login);add(form);pack();setSize(new Dimension(720,380));setLocationRelativeTo(null);}private void login(){String user=username.getText().trim();char[] entered=password.getPassword();if(user.isEmpty()||entered.length==0){error.setText("Enter username and password.");return;}if(UserAuthentication.login(user,entered)){AuditLogDAO.logActivity(user,"USER_LOGIN","User logged in successfully",new Timestamp(System.currentTimeMillis()));ActivityLogger.logAs(user,"Security","USER LOGIN","User logged in successfully","SUCCESS");dispose();PayrollSystemFrame app=new PayrollSystemFrame();app.setVisible(true);}else{AuditLogDAO.logActivity(user,"LOGIN_FAILED","Failed login attempt for username: "+user,new Timestamp(System.currentTimeMillis()));ActivityLogger.logAs(user,"Security","LOGIN FAILED","Invalid username or password","FAILED");error.setText("Invalid username or password.");password.setText("");}}}
